create table public.clubs (
 id uuid primary key default extensions.gen_random_uuid(), name text not null check(length(trim(name)) between 2 and 160), external_slug text not null unique check(external_slug ~ '^[a-z0-9][a-z0-9-]{1,100}$'), source_url text not null check(source_url like 'https://esports.tunesf.com/e-community/club/%'), season integer not null default 2026, created_at timestamptz not null default now()
);
alter table public.clubs enable row level security;
revoke all on public.clubs from public,anon,authenticated;
grant select on public.clubs to anon,authenticated;
create policy clubs_public_directory_read on public.clubs for select to anon,authenticated using(true);
