create table public.team_game_rosters(team_id uuid not null references public.teams(id) on delete cascade,game text not null check(game in ('cs2','val','lol','rl','eafc')),created_at timestamptz not null default now(),primary key(team_id,game));
create table public.team_game_members(team_id uuid not null,game text not null,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(team_id,game,user_id),foreign key(team_id,game) references public.team_game_rosters(team_id,game) on delete cascade,foreign key(team_id,user_id) references public.team_members(team_id,user_id) on delete cascade);
create index team_game_members_user_idx on public.team_game_members(user_id,game,team_id);
alter table public.team_game_rosters enable row level security; alter table public.team_game_members enable row level security;
revoke all on public.team_game_rosters,public.team_game_members from public,anon,authenticated;
grant select on public.team_game_rosters,public.team_game_members to anon,authenticated;
create policy team_game_rosters_public_read on public.team_game_rosters for select to anon,authenticated using(true);
create policy team_game_members_public_read on public.team_game_members for select to anon,authenticated using(true);
insert into public.team_game_rosters(team_id,game) select id,game from public.teams on conflict do nothing;
insert into public.team_game_members(team_id,game,user_id) select m.team_id,t.game,m.user_id from public.team_members m join public.teams t on t.id=m.team_id where m.status='active' on conflict do nothing;
create table public.team_join_requests(id uuid primary key default extensions.gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,game text not null,message text not null check(length(trim(message)) between 5 and 2000),status text not null default 'pending' check(status in ('pending','accepted','declined')),created_at timestamptz not null default now(),reviewed_at timestamptz,unique(team_id,user_id,game),foreign key(team_id,game) references public.team_game_rosters(team_id,game) on delete cascade);
create index team_join_requests_captain_inbox_idx on public.team_join_requests(team_id,status,created_at desc);
create table public.team_contact_messages(id uuid primary key default extensions.gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,message text not null check(length(trim(message)) between 1 and 2000),created_at timestamptz not null default now(),read_at timestamptz);
create index team_contact_messages_captain_inbox_idx on public.team_contact_messages(team_id,created_at desc); create index team_contact_messages_sender_idx on public.team_contact_messages(sender_id,created_at desc);
alter table public.team_join_requests enable row level security; alter table public.team_contact_messages enable row level security;
revoke all on public.team_join_requests,public.team_contact_messages from public,anon,authenticated;
create or replace function public.list_public_clubs() returns table(club_id uuid,name text,source_url text,season integer,team_id uuid,tag text,game text,region text,captain_name text,roster_size integer) language sql stable security definer set search_path='' as $$ select c.id,c.name,c.source_url,c.season,null::uuid,null::text,null::text,null::text,null::text,0 from public.clubs c union all select null::uuid,t.name,''::text,0,t.id,t.tag,t.game,t.region,p.username,(select count(*)::integer from public.team_game_members gm join public.team_members m using(team_id,user_id) where gm.team_id=t.id and gm.game=t.game and m.status='active') from public.teams t join public.public_profiles p on p.id=t.captain_id order by name $$;
create or replace function public.list_public_team_rosters(p_team_id uuid) returns table(game text,user_id uuid,username text,player_name text,member_role text) language sql stable security definer set search_path='' as $$ select gm.game,gm.user_id,p.username,p.player_name,m.role from public.team_game_members gm join public.team_members m using(team_id,user_id) join public.public_profiles p on p.id=gm.user_id where gm.team_id=p_team_id and m.status='active' order by gm.game,case m.role when 'captain' then 0 else 1 end,m.created_at $$;
create or replace function public.set_team_games(p_team_id uuid,p_games text[]) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not private.is_team_captain(p_team_id) then raise exception 'Team captain required'; end if; if coalesce(cardinality(p_games),0)<1 or cardinality(p_games)>5 or not(p_games <@ array['cs2','val','lol','rl','eafc']::text[]) then raise exception 'Select supported game rosters'; end if; if exists(select 1 from public.tournament_registrations where team_id=p_team_id and status in ('pending','approved','checked_in')) and exists(select 1 from public.team_game_rosters where team_id=p_team_id and not(game=any(p_games))) then raise exception 'Rosters locked while registered'; end if; insert into public.team_game_rosters(team_id,game) select p_team_id,x from unnest(p_games) x on conflict do nothing; delete from public.team_game_rosters where team_id=p_team_id and not(game=any(p_games)); end $$;
create or replace function public.set_team_game_member(p_team_id uuid,p_game text,p_user_id uuid,p_active boolean) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not private.is_team_captain(p_team_id) then raise exception 'Team captain required'; end if; perform 1 from public.teams where id=p_team_id for update; if p_game not in ('cs2','val','lol','rl','eafc') or not exists(select 1 from public.team_game_rosters where team_id=p_team_id and game=p_game) or not exists(select 1 from public.team_members where team_id=p_team_id and user_id=p_user_id and status='active') then raise exception 'Choose active player and enabled game'; end if; if exists(select 1 from public.tournament_registrations where team_id=p_team_id and status in ('pending','approved','checked_in')) then raise exception 'Rosters locked while registered'; end if; if p_active then if (select count(*) from public.team_game_members where team_id=p_team_id and game=p_game)>=20 and not exists(select 1 from public.team_game_members where team_id=p_team_id and game=p_game and user_id=p_user_id) then raise exception 'Game roster full'; end if; insert into public.team_game_members(team_id,game,user_id) values(p_team_id,p_game,p_user_id) on conflict do nothing; else delete from public.team_game_members where team_id=p_team_id and game=p_game and user_id=p_user_id; end if; end $$;
create or replace function public.request_team_join(p_team_id uuid,p_game text,p_message text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not exists(select 1 from public.user_roles where user_id=auth.uid() and role_key='PLAYER') then raise exception 'PLAYER role required'; end if; if not exists(select 1 from public.teams where id=p_team_id) or not exists(select 1 from public.team_game_rosters where team_id=p_team_id and game=p_game) then raise exception 'Team game not found'; end if; if private.is_team_member(p_team_id) then raise exception 'Already a team member'; end if; if length(trim(coalesce(p_message,'')))<5 or length(trim(p_message))>2000 then raise exception 'Message length invalid'; end if; insert into public.team_join_requests(team_id,user_id,game,message) values(p_team_id,auth.uid(),p_game,trim(p_message)) on conflict(team_id,user_id,game) do update set message=excluded.message,status='pending',created_at=now(),reviewed_at=null returning id into v_id; return v_id; end $$;
create or replace function public.send_team_message(p_team_id uuid,p_message text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not exists(select 1 from public.user_roles where user_id=auth.uid() and role_key='PLAYER') then raise exception 'PLAYER role required'; end if; if not exists(select 1 from public.teams where id=p_team_id) or private.is_team_member(p_team_id) then raise exception 'Contact unavailable'; end if; if length(trim(coalesce(p_message,'')))<1 or length(trim(p_message))>2000 then raise exception 'Message length invalid'; end if; if (select count(*) from public.team_contact_messages where sender_id=auth.uid() and created_at>now()-interval '1 hour')>=10 then raise exception 'Message limit reached'; end if; insert into public.team_contact_messages(team_id,sender_id,message) values(p_team_id,auth.uid(),trim(p_message)) returning id into v_id; return v_id; end $$;
create or replace function public.get_team_captain_inbox(p_team_id uuid) returns table(item_id uuid,item_type text,user_id uuid,username text,message text,game text,status text,created_at timestamptz,read_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or not private.is_team_captain(p_team_id) then raise exception 'Team captain required'; end if; return query select r.id,'join_request'::text,r.user_id,p.username,r.message,r.game,r.status,r.created_at,null::timestamptz from public.team_join_requests r join public.public_profiles p on p.id=r.user_id where r.team_id=p_team_id union all select m.id,'message'::text,m.sender_id,p.username,m.message,null::text,null::text,m.created_at,m.read_at from public.team_contact_messages m join public.public_profiles p on p.id=m.sender_id where m.team_id=p_team_id order by created_at desc; end $$;
create or replace function public.review_team_join_request(p_request_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ declare v public.team_join_requests%rowtype; begin if auth.uid() is null or p_status not in ('accepted','declined') then raise exception 'Invalid review'; end if; select * into v from public.team_join_requests where id=p_request_id for update; if not found or not private.is_team_captain(v.team_id) then raise exception 'Team captain required'; end if; if v.status<>'pending' then raise exception 'Already reviewed'; end if; if p_status='accepted' then perform 1 from public.teams where id=v.team_id for update; if exists(select 1 from public.tournament_registrations where team_id=v.team_id and status in ('pending','approved','checked_in')) then raise exception 'Roster locked'; end if; if private.is_team_member(v.team_id) then raise exception 'Already belongs'; end if; if (select count(*) from public.team_members where team_id=v.team_id and status='active' and role<>'substitute')>=20 then raise exception 'Roster full'; end if; insert into public.team_members(team_id,user_id,role,status) values(v.team_id,v.user_id,'player','active') on conflict(team_id,user_id) do update set role='player',status='active',created_at=now() where public.team_members.status='removed' and public.team_members.role<>'captain'; if not found then raise exception 'Existing membership prevents joining'; end if; insert into public.team_game_members(team_id,game,user_id) values(v.team_id,v.game,v.user_id) on conflict do nothing; end if; update public.team_join_requests set status=p_status,reviewed_at=now() where id=v.id; end $$;
create or replace function public.mark_team_message_read(p_message_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_team_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select team_id into v_team_id from public.team_contact_messages where id=p_message_id for update; if v_team_id is null or not private.is_team_captain(v_team_id) then raise exception 'Team captain required'; end if; update public.team_contact_messages set read_at=now() where id=p_message_id and read_at is null; end $$;
revoke all on function public.list_public_clubs(),public.list_public_team_rosters(uuid),public.set_team_games(uuid,text[]),public.set_team_game_member(uuid,text,uuid,boolean),public.request_team_join(uuid,text,text),public.send_team_message(uuid,text),public.get_team_captain_inbox(uuid),public.review_team_join_request(uuid,text),public.mark_team_message_read(uuid) from public,anon,authenticated;
grant execute on function public.list_public_clubs(),public.list_public_team_rosters(uuid) to anon,authenticated;
grant execute on function public.set_team_games(uuid,text[]),public.set_team_game_member(uuid,text,uuid,boolean),public.request_team_join(uuid,text,text),public.send_team_message(uuid,text),public.get_team_captain_inbox(uuid),public.review_team_join_request(uuid,text),public.mark_team_message_read(uuid) to authenticated;
